// CandidateListDrawer.tsx — Image 8 exact UI
// Modal drawer: Candidate Selection > job code + title > table of candidates
import React, { useState } from "react";
import styles from "./CandidateListDrawer.module.scss";
import { ReviewScorecardCandidate, ReviewScorecardJob } from "../../services/IEvaluationService";


interface Props {
  open:        boolean;
  job:         ReviewScorecardJob | null;
  candidates:  ReviewScorecardCandidate[];
  loading:     boolean;
  selectedId:  number | null;
  onSelect:    (c: ReviewScorecardCandidate) => void;
  onConfirm:   (c: ReviewScorecardCandidate) => void;
  onCancel:    () => void;
}

const GPA_COLORS = ["#22c55e", "#3b82f6", "#f59e0b", "#ef4444"];
const gpaColor = (gpa: number | string) => {
  const n = Number(gpa);
  if (n >= 4.5) return GPA_COLORS[0];
  if (n >= 3.5) return GPA_COLORS[1];
  if (n >= 2.5) return GPA_COLORS[2];
  return GPA_COLORS[3];
};

const CandidateListDrawer: React.FC<Props> = ({
  open, job, candidates, loading, selectedId, onSelect, onConfirm, onCancel
}) => {
  if (!open) return null;

  const selected = candidates.find(c => c.id === selectedId) ?? null;

  return (
    <div className={styles.overlay}>
      <div className={styles.modal}>
        {/* Header */}
        <div className={styles.header}>
          <div className={styles.headerLeft}>
            <div className={styles.avatar}>
              <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="#1a73e8" strokeWidth="2"><path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/></svg>
            </div>
            <div>
              <h2 className={styles.title}>Candidate Selection</h2>
              <div className={styles.jobInfo}>
                <span className={styles.jobCode}>{job?.jobCode}</span>
                <span className={styles.jobDot}>•</span>
                <span className={styles.jobTitle}>{job?.jobTitle?.toUpperCase()}</span>
              </div>
            </div>
          </div>
          <button className={styles.closeBtn} onClick={onCancel}>✕</button>
        </div>

        {/* Table */}
        <div className={styles.tableWrap}>
          {loading ? (
            <div className={styles.loadingWrap}><div className={styles.spinner} /></div>
          ) : (
            <table className={styles.table}>
              <thead>
                <tr>
                  <th>S.NO</th>
                  <th>APPLICANT NAME</th>
                  <th>POSITION TITLE</th>
                  <th>INTERVIEW LEVELS</th>
                  <th>GRADE</th>
                  <th>GPA</th>
                  <th>STATUS</th>
                  <th>ACTION</th>
                </tr>
              </thead>
              <tbody>
                {candidates.map((c) => (
                  <tr
                    key={c.id}
                    className={`${styles.row} ${selectedId === c.id ? styles.rowSelected : ""}`}
                  >
                    <td className={styles.sno}>{c.sNo}</td>
                    <td className={styles.nameCell}>{c.applicantName}</td>
                    <td className={styles.posCell}>{c.positionTitle}</td>
                    <td>{c.interviewLevel}</td>
                    <td>{c.grade}</td>
                    <td>
                      {/* Image 8: GPA badge with color */}
                      <span className={styles.gpaBadge} style={{ background: gpaColor(c.gpa) + "20", color: gpaColor(c.gpa), border: `1px solid ${gpaColor(c.gpa)}40` }}>
                        {c.gpa}
                      </span>
                    </td>
                    <td>
                      {/* Image 8: amber "Pending with HOD to select the candidate" tag */}
                      <span className={styles.statusTag}>
                        <span className={styles.statusDot} />
                        {c.status}
                      </span>
                    </td>
                    <td>
                      {/* Image 8: pencil edit icon */}
                      <button className={styles.editBtn} onClick={() => onSelect(c)} title="Review">
                        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>
                      </button>
                    </td>
                  </tr>
                ))}
                {candidates.length === 0 && (
                  <tr><td colSpan={8} className={styles.empty}>No candidates found.</td></tr>
                )}
              </tbody>
            </table>
          )}
        </div>

        {/* Footer */}
        <div className={styles.footer}>
          <div className={styles.footerInfo}>
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#9ca3af" strokeWidth="2"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg>
            <span>Please select a candidate to proceed</span>
          </div>
          <div className={styles.footerBtns}>
            <button className={styles.cancelBtn} onClick={onCancel}>CANCEL</button>
            <button
              className={[styles.confirmBtn, !selected ? styles.confirmBtnOff : ""].filter(Boolean).join(" ")}
              onClick={() => selected && onConfirm(selected)}
              disabled={!selected}
            >
              CONFIRM SELECTION
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default CandidateListDrawer;